import type { Metadata } from "next";
import { OG_IMAGE_ALT, SITE_NAME } from "@/lib/site";

/**
 * The social-sharing image generated by src/app/opengraph-image.tsx. Listed
 * explicitly because metadata merges shallowly: a page that sets `openGraph`
 * replaces the parent's object, file-based image included.
 */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: OG_IMAGE_ALT,
};

interface PageMetadataInput {
  /** Page title without the site-name suffix (unless `absoluteTitle`). */
  title: string;
  description: string;
  /** Canonical path, e.g. `/examples/promises`. */
  path: string;
  /** Use `title` as-is instead of appending " | JS/TS Playground". */
  absoluteTitle?: boolean;
}

/** Complete per-page metadata: title, description, canonical URL and Open Graph. */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: PageMetadataInput): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title: fullTitle,
      description,
      images: [OG_IMAGE],
    },
  };
}
